  } sticky_storage_t;

  typedef struct {
    bit_storage_t rst;
  } ctrl_storage_t;

  typedef struct {
    bit_storage_t rxc;
    bit_storage_t rwf;
    bit_storage_t rwe;
  } ier_storage_t;

  typedef struct {
    sticky_storage_t rxc;
    sticky_storage_t rwf;
    sticky_storage_t rwe;
  } isr_storage_t;

  typedef struct {
    ctrl_storage_t ctrl;
    ier_storage_t  ier;
    isr_storage_t  isr;
  } field_storage_t;

