  field_storage_t field_storage;

  logic [31:0] rd_mux_addr;
  logic        readback_err;
  logic        readback_done;
  logic [31:0] readback_data;

  // Leaf clears: Verilator 5.020 emits `struct = 0` for a packed `'0`.
  // rwe resets to 1, matching the VHDL sticky-empty default.
  initial begin
    field_storage.ctrl.rst.value = 1'b0;
    field_storage.ier.rxc.value  = 1'b0;
    field_storage.ier.rwf.value  = 1'b0;
    field_storage.ier.rwe.value  = 1'b0;
    field_storage.isr.rxc.value  = 1'b0;
    field_storage.isr.rxc.next_q = 1'b0;
    field_storage.isr.rwf.value  = 1'b0;
    field_storage.isr.rwf.next_q = 1'b0;
    field_storage.isr.rwe.value  = 1'b1;
    field_storage.isr.rwe.next_q = 1'b1;
