  assign cpuif_req            = s_cpuif_req;
  assign cpuif_req_is_wr      = s_cpuif_req_is_wr;
  assign cpuif_addr           = s_cpuif_addr;
  assign cpuif_wr_data        = s_cpuif_wr_data;
  assign cpuif_wr_biten       = s_cpuif_wr_biten;
  assign s_cpuif_req_stall_wr = cpuif_req_stall_wr;
  assign s_cpuif_req_stall_rd = cpuif_req_stall_rd;
  assign s_cpuif_rd_ack       = cpuif_rd_ack;
  assign s_cpuif_rd_err       = cpuif_rd_err;
  assign s_cpuif_rd_data      = cpuif_rd_data;
  assign s_cpuif_wr_ack       = cpuif_wr_ack;
  assign s_cpuif_wr_err       = cpuif_wr_err;

  assign cpuif_req_stall_rd = 1'b0;
  assign cpuif_req_stall_wr = 1'b0;
  assign cpuif_req_masked   = cpuif_req
    & ~((~cpuif_req_is_wr) & cpuif_req_stall_rd)
    & ~(cpuif_req_is_wr & cpuif_req_stall_wr);

  function automatic logic addr_is(input logic [31:0] addr, input int unsigned value);
    return reg_utils::to_std_logic(reg_utils::regvec#(32)::to_unsigned(addr) == 32'(value));
  endfunction

  always_comb begin : proc_decode
    decoded_reg_strb.ctrl   = cpuif_req_masked & addr_is(cpuif_addr, 32'h0) & cpuif_req_is_wr;
    decoded_reg_strb.ier    = cpuif_req_masked & addr_is(cpuif_addr, 32'h4);
    decoded_reg_strb.isr    = cpuif_req_masked & addr_is(cpuif_addr, 32'h8);
    decoded_reg_strb.fill   = cpuif_req_masked & addr_is(cpuif_addr, 32'hC) & ~cpuif_req_is_wr;
    decoded_reg_strb.length = cpuif_req_masked & addr_is(cpuif_addr, 32'h10) & ~cpuif_req_is_wr;
    decoded_reg_strb.read   = cpuif_req_masked & addr_is(cpuif_addr, 32'h14) & ~cpuif_req_is_wr;
    decoded_reg_strb.src    = cpuif_req_masked & addr_is(cpuif_addr, 32'h18) & ~cpuif_req_is_wr;
