  assign decoded_addr      = cpuif_addr;
  assign decoded_req       = cpuif_req_masked;
  assign decoded_req_is_wr = cpuif_req_is_wr;
  assign decoded_wr_data   = cpuif_wr_data;
  assign decoded_wr_biten  = cpuif_wr_biten;

  always_comb begin : proc_field_combo
    logic next_c;
    logic load_next_c;

    next_c      = field_storage.ctrl.rst.value;
    load_next_c = 1'b0;
    if (decoded_reg_strb.ctrl && decoded_req_is_wr) begin
      next_c      = (field_storage.ctrl.rst.value & ~decoded_wr_biten[0])
                  | (decoded_wr_data[0] & decoded_wr_biten[0]);
      load_next_c = 1'b1;
    end else begin
      next_c      = 1'b0;
      load_next_c = 1'b1;
    end
    field_combo.ctrl.rst.next_q    = next_c;
    field_combo.ctrl.rst.load_next = load_next_c;

    next_c      = field_storage.ier.rxc.value;
    load_next_c = 1'b0;
    if (decoded_reg_strb.ier && decoded_req_is_wr) begin
      next_c      = (field_storage.ier.rxc.value & ~decoded_wr_biten[0])
                  | (decoded_wr_data[0] & decoded_wr_biten[0]);
      load_next_c = 1'b1;
    end
    field_combo.ier.rxc.next_q    = next_c;
    field_combo.ier.rxc.load_next = load_next_c;

    next_c      = field_storage.ier.rwf.value;
    load_next_c = 1'b0;
    if (decoded_reg_strb.ier && decoded_req_is_wr) begin
      next_c      = (field_storage.ier.rwf.value & ~decoded_wr_biten[1])
                  | (decoded_wr_data[1] & decoded_wr_biten[1]);
      load_next_c = 1'b1;
    end
    field_combo.ier.rwf.next_q    = next_c;
    field_combo.ier.rwf.load_next = load_next_c;

    next_c      = field_storage.ier.rwe.value;
    load_next_c = 1'b0;
    if (decoded_reg_strb.ier && decoded_req_is_wr) begin
      next_c      = (field_storage.ier.rwe.value & ~decoded_wr_biten[2])
                  | (decoded_wr_data[2] & decoded_wr_biten[2]);
      load_next_c = 1'b1;
    end
    field_combo.ier.rwe.next_q    = next_c;
    field_combo.ier.rwe.load_next = load_next_c;

    next_c      = field_storage.isr.rxc.value;
    load_next_c = 1'b0;
    if (decoded_reg_strb.isr && decoded_req_is_wr) begin
      next_c      = field_storage.isr.rxc.value & ~(decoded_wr_data[0] & decoded_wr_biten[0]);
      load_next_c = 1'b1;
    end else if (reg_utils::or_reduce_sl(~field_storage.isr.rxc.next_q & hwif_in.isr.rxc.next_q)) begin
      next_c      = 1'b1;
      load_next_c = 1'b1;
    end
    field_combo.isr.rxc.next_q    = next_c;
    field_combo.isr.rxc.load_next = load_next_c;

    next_c      = field_storage.isr.rwf.value;
    load_next_c = 1'b0;
    if (decoded_reg_strb.isr && decoded_req_is_wr) begin
      next_c      = field_storage.isr.rwf.value & ~(decoded_wr_data[1] & decoded_wr_biten[1]);
      load_next_c = 1'b1;
    end else if (reg_utils::or_reduce_sl(~field_storage.isr.rwf.next_q & hwif_in.isr.rwf.next_q)) begin
      next_c      = 1'b1;
      load_next_c = 1'b1;
