      if (field_combo.ctrl.rst.load_next)
        field_storage.ctrl.rst.value <= field_combo.ctrl.rst.next_q;
      if (field_combo.ier.rxc.load_next)
        field_storage.ier.rxc.value <= field_combo.ier.rxc.next_q;
      if (field_combo.ier.rwf.load_next)
        field_storage.ier.rwf.value <= field_combo.ier.rwf.next_q;
      if (field_combo.ier.rwe.load_next)
        field_storage.ier.rwe.value <= field_combo.ier.rwe.next_q;
      if (field_combo.isr.rxc.load_next)
        field_storage.isr.rxc.value <= field_combo.isr.rxc.next_q;
      field_storage.isr.rxc.next_q <= hwif_in.isr.rxc.next_q;
      if (field_combo.isr.rwf.load_next)
        field_storage.isr.rwf.value <= field_combo.isr.rwf.next_q;
      field_storage.isr.rwf.next_q <= hwif_in.isr.rwf.next_q;
      if (field_combo.isr.rwe.load_next)
        field_storage.isr.rwe.value <= field_combo.isr.rwe.next_q;
      field_storage.isr.rwe.next_q <= hwif_in.isr.rwe.next_q;
    end
  end

  always_comb begin : proc_hwif_out
    hwif_out.ctrl.rst.value = field_storage.ctrl.rst.value;
    hwif_out.isr.intr       = (field_storage.isr.rxc.value & field_storage.ier.rxc.value)
