    if (rd_mux_addr == 32'h4) begin
      readback_data_var[0] = field_storage.ier.rxc.value;
      readback_data_var[1] = field_storage.ier.rwf.value;
      readback_data_var[2] = field_storage.ier.rwe.value;
    end
    if (rd_mux_addr == 32'h8) begin
      readback_data_var[0] = field_storage.isr.rxc.value;
      readback_data_var[1] = field_storage.isr.rwf.value;
      readback_data_var[2] = field_storage.isr.rwe.value;
    end
    if (rd_mux_addr == 32'hC)
      readback_data_var = hwif_in.fill.usedw.next_q;
    if (rd_mux_addr == 32'h10)
      readback_data_var = hwif_in.length.bytes.next_q;
    if (rd_mux_addr == 32'h14)
      readback_data_var = hwif_in.read.data.next_q;
    if (rd_mux_addr == 32'h18)
      readback_data_var = hwif_in.src.id.next_q;
    readback_data = readback_data_var;
    readback_done = decoded_req & ~decoded_req_is_wr;
    readback_err  = 1'b0;
  end

  assign cpuif_rd_ack  = readback_done;
  assign cpuif_rd_data = readback_data;
  assign cpuif_rd_err  = readback_err;

